function flagEmoji(countryCode) {
  if (!countryCode || countryCode.length !== 2) return '';
  const A = 0x1F1E6;
  return String.fromCodePoint(...countryCode.toUpperCase().split('').map(c => A + (c.charCodeAt(0) - 65)));
}
