    const actuellesDone = Array.from({ length: 12 }, (_, i) => {
      const league = s.leagues[`Actuelles ${i + 1}`];
      const matches = league?.matches || [];
      return matches.length > 0 && matches.every(m => m.homeGoals !== null);
    }).every(Boolean);
