      seasons[si] = prev;

      const newNum = prev.season + 1;
      const ns = { season: newNum, leagues: {}, champions: {}, relegated: {} };

      const succLeague = prev.leagues['Successeurs'];
      const succCars = succLeague?.cars || [];
      const succMatches = succLeague?.matches || [];
