                                  {isPlayed ? (<><span style={{ color:hWin ? 'var(--green)' :aWin ? '#e74c3c' :'var(--gold)' }}>{m.homeGoals}</span><span style={{ color:'var(--text-dim)' }}> : </span><span style={{ color:aWin ? 'var(--green)' :hWin ? '#e74c3c' :'var(--gold)' }}>{m.awayGoals}</span></>) : <span style={{ color:'var(--text-dim)' }}>— : —</span>}
